<div style="display:flex;gap:4px;">
  <button id="btnPrev">◀ Prev</button>
  <button id="btnPlay">▶ Play</button>
  <button id="btnNext">Next ▶</button>
</div>
<div id="demoTitle" style="font-weight:bold;margin-top:2px;"></div>
<div id="demoText" style="line-height:1.35;color:#333;"></div>
<div style="margin-top:6px;color:#666;line-height:1.35;">
  Hover a datapoint to trace its whole path through the stack. Drag to orbit — the blue bow-out is a real lateral displacement. Click a plane for an explanation.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC
   plane fill        -> PlaneGeometry(2,2) rot -90deg X, MeshBasicMaterial white, opacity .12, depthWrite:false
   plane grid 4x4    -> LineSegments, #cccccc
   plane border      -> Line loop of 4 corners, #444444
   corner scaffolding-> Line (dashed) #999999 between matching corners of adjacent planes
   red points        -> InstancedMesh SphereGeometry(0.035) color #ee1111
   blue points       -> same InstancedMesh, color #1111ee
   pick proxy        -> InstancedMesh SphereGeometry(0.13) opacity 0 (hover raycast)
   trajectories      -> one CatmullRomCurve3 per datapoint through 7 plane positions -> Line + LineDashedMaterial
   legend arrows     -> Line shaft + ConeGeometry head, #222222, at screen-left anti-diagonal
   legend labels     -> addLabel rounded boxes: linear/relu/linear/relu/linear/softmax
   training axis     -> Line + Cone head along screen-horizontal (1,0,-1), ticks = short Y segments,
                        ellipses = small spheres, handle = cone riding the axis
*/

const RED = 0xee1111, BLUE = 0x1111ee;
const PLANE_Y = [0, 1.6, 3.2, 4.8, 6.4, 8.0, 9.6];
const N = 70, SAMP = 72, PER = 12;
const lerp = (a, b, u) => a + (b - a) * u;

const root = new THREE.Group();
scene.add(root);

/* ── seeded rng ─────────────────────────────────────────────── */
let _s = 20240613;
function rnd() { _s = (_s * 1664525 + 1013904223) % 4294967296; return _s / 4294967296; }

/* ── planes ─────────────────────────────────────────────────── */
const PLANE_INFO = [
  ['Input data', 'The raw 2-D input cloud: red and blue points are thoroughly intermingled in a dense central cluster. No layer has acted yet.'],
  ['After linear 1', 'A linear map (matrix multiply + bias) rotates, stretches and shears the whole cloud. It cannot fold, so overlapping classes stay overlapping.'],
  ['After relu 1', 'ReLU clamps negative coordinates to zero, folding part of the cloud onto the plane\'s axis lines — that is the visible line/corner concentration.'],
  ['After linear 2', 'A second linear map re-orients the folded cloud, lining the classes up for the next fold.'],
  ['After relu 2', 'A second ReLU fold. Red is now drawn towards the column axis while blue is pushed laterally.'],
  ['After linear 3', 'The final linear layer produces class logits; red collapses to a tight vertical bundle, blue swings outward.'],
  ['Softmax', 'Softmax squashes the logits onto the class simplex. Well trained, red collapses near one corner and blue near the opposite one.']
];
const planes = [];
for (let L = 0; L < 7; L++) {
  const g = new THREE.Group();
  g.position.y = PLANE_Y[L];

  const fillMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.12, depthWrite: false, side: THREE.DoubleSide });
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), fillMat);
  fill.rotation.x = -Math.PI / 2;
  fill.renderOrder = 2;
  g.add(fill);

  const gp = [];
  for (let k = 0; k <= 4; k++) { const u = -1 + k * 0.5; gp.push(-1, 0, u, 1, 0, u, u, 0, -1, u, 0, 1); }
  const gridMat = new THREE.LineBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.95 });
  const grid = new THREE.LineSegments(new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(gp, 3)), gridMat);
  grid.renderOrder = 2; g.add(grid);

  const bMat = new THREE.LineBasicMaterial({ color: 0x444444, transparent: true, opacity: 1 });
  const bg = new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(
    [-1, 0, -1, 1, 0, -1, 1, 0, 1, -1, 0, 1, -1, 0, -1], 3));
  const border = new THREE.Line(bg, bMat);
  border.renderOrder = 3; g.add(border);

  root.add(g);
  planes.push({ g, fillMat, gridMat, bMat });
  registerInteractive(fill, { title: PLANE_INFO[L][0], body: PLANE_INFO[L][1], tooltip: PLANE_INFO[L][0] });
}

/* ── corner scaffolding ─────────────────────────────────────── */
const scaffold = [];
const CORN = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
for (let L = 0; L < 6; L++) {
  const mat = new THREE.LineDashedMaterial({ color: 0x999999, dashSize: 0.06, gapSize: 0.06, transparent: true, opacity: 0.9 });
  const pos = [];
  for (const c of CORN) { pos.push(c[0], PLANE_Y[L], c[1], c[0], PLANE_Y[L + 1], c[1]); }
  const geo = new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  const ls = new THREE.LineSegments(geo, mat);
  ls.computeLineDistances(); ls.renderOrder = 0;
  root.add(ls); scaffold.push(mat);
}

/* ── datapoints & trajectories ──────────────────────────────── */
function blueOffset(t) {
  const ks = [0.3, 0.9, 1.6, 2.6];
  const x = Math.min(0.999, Math.max(0, t)) * 3;
  const i = Math.min(2, Math.floor(x));
  return lerp(ks[i], ks[i + 1], x - i);
}

const data = [];
for (let i = 0; i < N; i++) {
  const r = 0.35 * Math.sqrt(rnd()), a = rnd() * Math.PI * 2;
  const p = {
    cls: i % 2, bx: r * Math.cos(a), bz: r * Math.sin(a),
    fan: 0.55 + 0.85 * rnd(), sgn: rnd() < 0.5 ? -1 : 1,
    clamp: (i % 3 === 0), j: [], P: []
  };
  for (let L = 0; L < 7; L++) { p.j.push([(rnd() - 0.5), (rnd() - 0.5)]); p.P.push(new THREE.Vector3()); }
  const col = p.cls ? BLUE : RED;
  p.mat = new THREE.LineDashedMaterial({ color: col, dashSize: 0.05, gapSize: 0.05, transparent: true, opacity: 0.55 });
  p.arr = new Float32Array((SAMP + 1) * 3);
  p.geom = new THREE.BufferGeometry();
  p.geom.setAttribute('position', new THREE.BufferAttribute(p.arr, 3));
  p.line = new THREE.Line(p.geom, p.mat);
  p.line.renderOrder = 1; p.line.frustumCulled = false;
  p.curve = new THREE.CatmullRomCurve3(p.P, false, 'catmullrom', 0.4);
  root.add(p.line);
  data.push(p);
}

function posOf(p, L, t, out) {
  const f = L / 6;
  let x, z;
  if (p.cls === 0) {
    const s = lerp(1, lerp(0.25, 0.08, t) / 0.35, f);
    x = p.bx * s - 0.22 * f * f * t;
    z = p.bz * s;
  } else {
    const s = lerp(1, lerp(0.30, 0.14, t) / 0.35, f);
    const off = blueOffset(t) * Math.pow(f, 1.7) * p.fan;
    x = p.bx * s + off;
    z = p.bz * s + p.sgn * 0.18 * Math.pow(f, 1.6) * blueOffset(t) * 0.35;
  }
  const js = 0.05 + 0.10 * (1 - f);
  x += p.j[L][0] * js; z += p.j[L][1] * js;
  if ((L === 2 || L === 4) && p.clamp) z = 0;            // relu folds onto axis line
  if (L === 6) { x *= 0.9; z *= 0.6; }                   // softmax collapse
  out.set(x, PLANE_Y[L], z);
}

const sphereGeo = new THREE.SphereGeometry(0.035, 10, 8);
const ptsMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0.85 });
const ptsMesh = new THREE.InstancedMesh(sphereGeo, ptsMat, N * 7);
ptsMesh.renderOrder = 4; ptsMesh.frustumCulled = false;
root.add(ptsMesh);

const pickMesh = new THREE.InstancedMesh(new THREE.SphereGeometry(0.13, 6, 5),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }), N * 7);
pickMesh.frustumCulled = false; root.add(pickMesh);

const dummy = new THREE.Object3D();
const cTmp = new THREE.Color(), cW = new THREE.Color(0xffffff), tmpV = new THREE.Vector3();

/* ── legend column (screen-left: z = -x keeps it level) ─────── */
const LX = -2.2, LZ = 2.2;
const legMat = new THREE.LineBasicMaterial({ color: 0x222222 });
const headMat = new THREE.MeshBasicMaterial({ color: 0x222222 });
for (let k = 0; k < 7; k++) {
  const y = PLANE_Y[k];
  const g = new THREE.BufferGeometry().setAttribute('position',
    new THREE.Float32BufferAttribute([LX, y - 0.38, LZ, LX, y + 0.20, LZ], 3));
  root.add(new THREE.Line(g, legMat));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.18, 12), headMat);
  head.position.set(LX, y + 0.29, LZ);
  root.add(head);
}
const LEG = ['linear', 'relu', 'linear', 'relu', 'linear', 'softmax'];
LEG.forEach((txt, k) => {
  const e = addLabel(txt, new THREE.Vector3(LX, PLANE_Y[k] + 0.8, LZ), { fontSize: '12px' });
  e.div.style.fontFamily = 'ui-monospace, Consolas, monospace';
  e.div.style.background = '#fff';
  e.div.style.border = '1px solid #444';
  e.div.style.borderRadius = '9px';
  e.div.style.padding = '2px 7px';
});

/* ── training-iteration axis (screen-horizontal) ────────────── */
const AY = -1.35;
const A0 = new THREE.Vector3(-2.2, AY, 2.2), A1 = new THREE.Vector3(3.2, AY, -3.2);
const axisDir = A1.clone().sub(A0);
root.add(new THREE.Line(new THREE.BufferGeometry().setAttribute('position',
  new THREE.Float32BufferAttribute([A0.x, A0.y, A0.z, A1.x, A1.y, A1.z], 3)),
  new THREE.LineBasicMaterial({ color: 0x111111 })));
const aHead = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.26, 14), new THREE.MeshBasicMaterial({ color: 0x111111 }));
aHead.position.copy(A1);
aHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), axisDir.clone().normalize());
root.add(aHead);
const axisAt = (u) => A0.clone().addScaledVector(axisDir, u);
const TICK_U = [0.12, 0.38, 0.64, 0.90];
TICK_U.forEach(u => {
  const p = axisAt(u);
  root.add(new THREE.Line(new THREE.BufferGeometry().setAttribute('position',
    new THREE.Float32BufferAttribute([p.x, p.y - 0.10, p.z, p.x, p.y + 0.10, p.z], 3)),
    new THREE.LineBasicMaterial({ color: 0x111111 })));
});
const dotMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
[0.51, 0.77].forEach(uc => {
  for (let k = -1; k <= 1; k++) {
    const m = new THREE.Mesh(new THREE.SphereGeometry(0.045, 8, 6), dotMat);
    m.position.copy(axisAt(uc + k * 0.035)).add(new THREE.Vector3(0, 0.20, 0));
    root.add(m);
  }
});
const handle = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.24, 14), new THREE.MeshBasicMaterial({ color: 0xcc2222 }));
handle.rotation.x = Math.PI;
root.add(handle);
const tiLbl = addLabel('Training iteration', axisAt(0.0), { fontSize: '13px', offset: [0, 22] });
tiLbl.div.style.fontFamily = 'Georgia, serif';

/* ── invisible framer so the camera fit covers the widest state ─ */
const framer = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshBasicMaterial({ visible: false }));
framer.scale.set(8.4, 12.4, 6.6);
framer.position.set(0.9, 4.5, 0);
root.add(framer);

/* ── state + update ─────────────────────────────────────────── */
let tIter = 0, stepIdx = 7, hovered = -1;

function update() {
  const t = tIter;
  const stepping = stepIdx < 7;
  const activeK = stepping ? stepIdx : 6;

  for (let i = 0; i < N; i++) {
    const p = data[i];
    for (let L = 0; L < 7; L++) posOf(p, L, t, p.P[L]);
    for (let k = 0; k <= SAMP; k++) {
      p.curve.getPoint(k / SAMP, tmpV);
      p.arr[3 * k] = tmpV.x; p.arr[3 * k + 1] = tmpV.y; p.arr[3 * k + 2] = tmpV.z;
    }
    p.geom.attributes.position.needsUpdate = true;
    p.geom.computeBoundingSphere();
    p.line.computeLineDistances();
    p.geom.setDrawRange(0, stepping ? activeK * PER + 1 : SAMP + 1);
    p.mat.opacity = hovered >= 0 ? (i === hovered ? 1.0 : 0.05) : 0.55;
    p.line.renderOrder = (i === hovered) ? 5 : 1;
  }

  for (let L = 0; L < 7; L++) {
    for (let i = 0; i < N; i++) {
      const p = data[i], id = L * N + i;
      const show = (!stepping || L <= activeK);
      dummy.position.copy(p.P[L]);
      dummy.scale.setScalar(show ? 1 : 0.0001);
      dummy.updateMatrix();
      ptsMesh.setMatrixAt(id, dummy.matrix);
      dummy.scale.setScalar(show ? 1 : 0.0001);
      dummy.updateMatrix();
      pickMesh.setMatrixAt(id, dummy.matrix);
      cTmp.setHex(p.cls ? BLUE : RED);
      if (hovered >= 0 && i !== hovered) cTmp.lerp(cW, 0.86);
      ptsMesh.setColorAt(id, cTmp);
    }
  }
  ptsMesh.instanceMatrix.needsUpdate = true;
  pickMesh.instanceMatrix.needsUpdate = true;
  if (ptsMesh.instanceColor) ptsMesh.instanceColor.needsUpdate = true;

  for (let L = 0; L < 7; L++) {
    const pl = planes[L];
    const above = stepping && L > activeK;
    const act = stepping && L === activeK;
    pl.fillMat.color.setHex(act ? 0xcfe4ff : 0xffffff);
    pl.fillMat.opacity = above ? 0.03 : (act ? 0.30 : 0.12);
    pl.bMat.color.setHex(act ? 0x000000 : 0x444444);
    pl.bMat.opacity = above ? 0.22 : 1.0;
    pl.gridMat.opacity = above ? 0.18 : 0.95;
  }
  scaffold.forEach((m, L) => { m.opacity = (stepping && L >= activeK) ? 0.2 : 0.9; });

  handle.position.copy(axisAt(TICK_U[0] + t * (TICK_U[3] - TICK_U[0]))).add(new THREE.Vector3(0, 0.30, 0));
}
update();

/* ── camera (after all geometry) ────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.72 });
document.getElementById('btnReset').style.display = '';

/* ── hover trajectory ───────────────────────────────────────── */
const hRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  hRay.setFromCamera(ndc, camera);
  const hits = hRay.intersectObject(pickMesh, false);
  let h = -1;
  if (hits.length && hits[0].instanceId !== undefined) h = hits[0].instanceId % N;
  if (h !== hovered) { hovered = h; update(); }
  if (h >= 0) showTooltip(`datapoint #${h} — class ${data[h].cls ? 'blue (1)' : 'red (0)'}: same point, all 7 layers`, e);
});
canvas.addEventListener('pointerleave', () => { if (hovered !== -1) { hovered = -1; update(); } });

/* ── UI wiring ──────────────────────────────────────────────── */
const slider = document.getElementById('trainingIteration');
const iterVal = document.getElementById('iterVal');
let tween = null;
function setIter(v) {
  tIter = Math.min(1, Math.max(0, v));
  slider.value = Math.round(tIter * 100);
  iterVal.textContent = Math.round(tIter * 100);
  update();
}
slider.addEventListener('input', () => { tween = null; setIter(+slider.value / 100); });

const STEPS = ['input', 'linear', 'relu', 'linear2', 'relu2', 'linear3', 'softmax', 'all'];
const stepBtns = Array.from(document.querySelectorAll('#stepBtns button'));
function setStep(name) {
  stepIdx = STEPS.indexOf(name);
  if (stepIdx < 0) stepIdx = 7;
  stepBtns.forEach(b => b.classList.toggle('active', b.dataset.step === STEPS[stepIdx]));
  update();
}
stepBtns.forEach(b => b.addEventListener('click', () => setStep(b.dataset.step)));

/* ── guided tour ────────────────────────────────────────────── */
const DEMO = [
  { title: 'Untrained network', narr: 'At the first iteration red and blue stay intermingled all the way up the stack; even the softmax plane shows the colours overlapping near the centre.', iter: 0, step: 'all' },
  { title: 'Bottom plane: the raw input', narr: 'The lowest plane is the untransformed data — a dense central cluster with red and blue thoroughly mixed. No layer has acted yet.', iter: 0, step: 'input' },
  { title: 'First linear, then relu', narr: 'Step up one plane at a time: the linear layer shears and spreads the cloud, then relu folds part of it, beginning to push blue off to one side.', iter: 0.33, step: 'relu' },
  { title: 'Mid-training, deeper layers', narr: 'Partway through training the upper linear layers already draw red into a narrow vertical bundle while blue trajectories bow out beyond the plane edge.', iter: 0.66, step: 'linear3' },
  { title: 'Converged softmax', narr: 'Late in training the softmax plane holds two tight, widely separated bundles — reading up the column shows how each layer contributed.', iter: 1, step: 'softmax' }
];
let demoIdx = -1, playing = false, playTimer = null;
const dTitle = document.getElementById('demoTitle'), dText = document.getElementById('demoText');
function goToStep(i) {
  demoIdx = ((i % DEMO.length) + DEMO.length) % DEMO.length;
  const s = DEMO[demoIdx];
  dTitle.textContent = `${demoIdx + 1}/${DEMO.length} · ${s.title}`;
  dText.textContent = s.narr;
  setStep(s.step);
  tween = { from: tIter, to: s.iter, t0: performance.now(), dur: 900 };
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(demoIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(demoIdx - 1));
const playBtn = document.getElementById('btnPlay');
playBtn.addEventListener('click', () => {
  playing = !playing;
  playBtn.textContent = playing ? '❚❚ Pause' : '▶ Play';
  playBtn.classList.toggle('active', playing);
  if (playing) { goToStep(demoIdx + 1); playTimer = setInterval(() => goToStep(demoIdx + 1), 4200); }
  else clearInterval(playTimer);
});

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const u = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = u < 0.5 ? 2 * u * u : 1 - 2 * (1 - u) * (1 - u);
    setIter(tween.from + (tween.to - tween.from) * e);
    if (u >= 1) tween = null;
  }
}
tick();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.
